// Package main verifies the rendered ToolHive authorization policies against
// ToolHive's OWN Cedar engine, rather than asserting that they look correct.
//
// The policies in deploy/environments/<env>/rendered/toolhive are generated by
// scripts/render-toolhive-authz.ts and handed to `thv run --authz-config`. This
// test loads the same YAML with the same authorizer ToolHive uses at runtime and
// checks the decisions that matter:
//
//   - the Agent the policy grants may call the tools it was granted
//   - a DIFFERENT Agent workload may not call them
//   - a tool nobody granted is denied even to the right Agent
//   - a server with no grants denies everyone
//
// Run with:
//
//	SRE_REPO=/path/to/repo go test ./scripts/toolhive-policy-check/...
//
// from inside the vendored ToolHive checkout, which is where the module lives.
// It is not part of `npm run check` because it needs the ToolHive source tree;
// `npm run verify:toolhive-policy` wires it up when that tree is present.
package main

import (
	"context"
	"os"
	"path/filepath"
	"testing"

	"github.com/stacklok/toolhive/pkg/auth"
	"github.com/stacklok/toolhive/pkg/authz/authorizers"
	"github.com/stacklok/toolhive/pkg/authz/authorizers/cedar"
	"gopkg.in/yaml.v3"
)

type renderedPolicy struct {
	Version string `yaml:"version"`
	Type    string `yaml:"type"`
	Cedar   struct {
		Policies     []string `yaml:"policies"`
		EntitiesJSON string   `yaml:"entities_json"`
	} `yaml:"cedar"`
}

func load(t *testing.T, path string) authorizers.Authorizer {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read %s: %v", path, err)
	}
	var parsed renderedPolicy
	if err := yaml.Unmarshal(raw, &parsed); err != nil {
		t.Fatalf("parse %s: %v", path, err)
	}
	if parsed.Type != "cedarv1" {
		t.Fatalf("%s: expected cedarv1, got %q", path, parsed.Type)
	}
	authorizer, err := cedar.NewCedarAuthorizer(cedar.ConfigOptions{
		Policies:     parsed.Cedar.Policies,
		EntitiesJSON: parsed.Cedar.EntitiesJSON,
	}, "")
	if err != nil {
		// a policy ToolHive cannot load is a policy that would fail the proxy at
		// startup, which is exactly what this catches before it ships
		t.Fatalf("%s: ToolHive rejected the rendered policy: %v", path, err)
	}
	return authorizer
}

// asWorkload builds the request context ToolHive would have after verifying a
// workload token: the human in `sub`, the Agent workload in `azp`.
func asWorkload(workloadClientID string) context.Context {
	identity := &auth.Identity{PrincipalInfo: auth.PrincipalInfo{
		Subject: "alice",
		Claims:  map[string]interface{}{"sub": "alice", "azp": workloadClientID},
	}}
	return auth.WithIdentity(context.Background(), identity)
}

func callTool(t *testing.T, authorizer authorizers.Authorizer, ctx context.Context, tool string) bool {
	t.Helper()
	allowed, err := authorizer.AuthorizeWithJWTClaims(ctx, authorizers.MCPFeatureTool, authorizers.MCPOperationCall, tool, nil)
	if err != nil {
		t.Fatalf("authorize %s: %v", tool, err)
	}
	return allowed
}

func repoRoot(t *testing.T) string {
	t.Helper()
	root := os.Getenv("SRE_REPO")
	if root == "" {
		t.Skip("SRE_REPO is not set")
	}
	return root
}

func policyPath(root, environment, server string) string {
	return filepath.Join(root, "deploy/environments", environment, "rendered/toolhive", server+".authz.yaml")
}

func TestRenderedPoliciesAreLoadableByToolHive(t *testing.T) {
	root := repoRoot(t)
	environments, err := os.ReadDir(filepath.Join(root, "deploy/environments"))
	if err != nil {
		t.Fatalf("read environments: %v", err)
	}
	for _, environment := range environments {
		dir := filepath.Join(root, "deploy/environments", environment.Name(), "rendered/toolhive")
		files, err := os.ReadDir(dir)
		if err != nil {
			t.Fatalf("read %s: %v", dir, err)
		}
		for _, file := range files {
			load(t, filepath.Join(dir, file.Name()))
		}
	}
}

func TestOnlyTheGrantedAgentMayCallItsTools(t *testing.T) {
	root := repoRoot(t)
	authorizer := load(t, policyPath(root, "production", "keycloak"))

	keycloakAgent := asWorkload("sre-agent-keycloak")
	otherAgent := asWorkload("sre-agent-observability")

	for _, tool := range []string{"list_realms", "list_clients", "keycloak_health", "find_user"} {
		if !callTool(t, authorizer, keycloakAgent, tool) {
			t.Errorf("sre-agent-keycloak should be permitted to call %s", tool)
		}
		// the whole point of the gateway-side policy: another Agent presenting a
		// valid token for this MCP still cannot call the tool
		if callTool(t, authorizer, otherAgent, tool) {
			t.Errorf("sre-agent-observability must NOT be permitted to call %s", tool)
		}
	}
}

func TestAnUngrantedToolIsDeniedToEveryone(t *testing.T) {
	root := repoRoot(t)
	authorizer := load(t, policyPath(root, "production", "keycloak"))
	for _, workload := range []string{"sre-agent-keycloak", "sre-agent-observability", "sre-agent-openshift"} {
		// not in the approved catalog and not in anyone's policy
		if callTool(t, authorizer, asWorkload(workload), "delete_realm") {
			t.Errorf("%s must not be permitted to call delete_realm", workload)
		}
	}
}

func TestAServerWithNoGrantsDeniesEveryone(t *testing.T) {
	root := repoRoot(t)
	// openshift is a canonical MCP server that no Agent may reach in the PoC
	authorizer := load(t, policyPath(root, "poc", "openshift"))
	for _, tool := range []string{"get_pod_status", "list_namespace_events"} {
		if callTool(t, authorizer, asWorkload("sre-agent-openshift"), tool) {
			t.Errorf("an empty policy set must deny %s", tool)
		}
	}
}

func TestAnUnknownWorkloadIsDenied(t *testing.T) {
	root := repoRoot(t)
	authorizer := load(t, policyPath(root, "production", "wiki"))
	// no azp at all, and an azp nobody provisioned
	for _, ctx := range []context.Context{
		auth.WithIdentity(context.Background(), &auth.Identity{PrincipalInfo: auth.PrincipalInfo{Subject: "alice", Claims: map[string]interface{}{"sub": "alice"}}}),
		asWorkload("sre-agent-not-a-real-agent"),
	} {
		if callTool(t, authorizer, ctx, "wiki_search") {
			t.Error("a workload outside the rendered policy must be denied")
		}
	}
}
